for name in ('PersonalScreen','CommandScreen','SettingsScreen','HudPositionScreen','OrderCardButton'):
    sources.pop('cc/crafto/ui/client/'+name+'.java',None)
sources['net/minecraft/client/gui/components/AbstractWidget.java']=r'''package net.minecraft.client.gui.components;
import net.minecraft.network.chat.Component;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.events.GuiEventListener;
public class AbstractWidget implements GuiEventListener{
 protected float alpha=1;public boolean active=true,visible=true,hovered,focused;public int x,y,w,h;public String label;public Runnable press;protected Component message;public Tooltip tooltip;
 public AbstractWidget(int x,int y,int w,int h,Component m){this.x=x;this.y=y;this.w=w;this.h=h;message=m;label=m.getString();}
 public void setTooltip(Tooltip t){tooltip=t;}public void setAlpha(float a){alpha=a;}public int getX(){return x;}public int getY(){return y;}public int getWidth(){return w;}public int getHeight(){return h;}public void setY(int v){y=v;}public void setX(int v){x=v;}public void setMessage(Component c){message=c;label=c.getString();}public Component getMessage(){return message;}public boolean isFocused(){return focused;}public void setFocused(boolean v){focused=v;}public boolean isHoveredOrFocused(){return hovered||focused;}public boolean isMouseOver(double mx,double my){return mx>=x&&mx<x+w&&my>=y&&my<y+h;}
 protected void extractWidgetRenderState(GuiGraphicsExtractor g,int mx,int my,float d){}public void render(GuiGraphicsExtractor g,int mx,int my,float d){if(!visible)return;hovered=isMouseOver(mx,my);extractWidgetRenderState(g,mx,my,d);}
}'''
sources['net/minecraft/client/gui/components/Button.java']=r'''package net.minecraft.client.gui.components;
import net.minecraft.network.chat.Component;import net.minecraft.client.gui.GuiGraphicsExtractor;import java.util.function.Consumer;
public class Button extends AbstractWidget{protected static final Object DEFAULT_NARRATION=new Object();
 public Button(String label,int x,int y,int w,int h,Runnable action){this(x,y,w,h,Component.literal(label),b->action.run(),DEFAULT_NARRATION);}
 public Button(int x,int y,int w,int h,Component m,Consumer<Button> action,Object n){super(x,y,w,h,m);press=()->action.accept(this);}
 protected void extractContents(GuiGraphicsExtractor g,int mx,int my,float d){}protected void extractWidgetRenderState(GuiGraphicsExtractor g,int mx,int my,float d){extractContents(g,mx,my,d);}
}'''
sources['net/minecraft/client/gui/components/EditBox.java']=r'''package net.minecraft.client.gui.components;
import net.minecraft.network.chat.Component;import net.minecraft.client.gui.*;import java.util.function.Consumer;
public class EditBox extends AbstractWidget{private String value="",hint="";private int cursor,max=32,color=0xFFFFFFFF;private Consumer<String> responder=s->{};private final Font font;
 public EditBox(Font f,int x,int y,int w,int h,Component c){super(x,y,w,h,c);font=f;}public void setResponder(Consumer<String> r){responder=r;}public void setMaxLength(int n){max=n;}public void setValue(String v){value=v.substring(0,Math.min(max,v.length()));cursor=value.length();responder.accept(value);}public String getValue(){return value;}public int getCursorPosition(){return cursor;}public void setCursorPosition(int n){cursor=Math.clamp(n,0,value.length());}public void insertText(String t){int old=cursor;setValue(value.substring(0,cursor)+t+value.substring(cursor));cursor=Math.min(value.length(),old+t.length());}public void setHint(Component c){hint=c.getString();}public void setBordered(boolean b){}public void setTextShadow(boolean b){}public void setTextColor(int c){color=c;}
 public void extractWidgetRenderState(GuiGraphicsExtractor g,int mx,int my,float d){g.text(font,font.plainSubstrByWidth(value.isEmpty()?hint:value,w-6),x+2,y+7,value.isEmpty()?0xFF80909F:color,false);if(focused){int cx=x+2+font.width(value.substring(0,cursor));g.fill(cx,y+5,cx+1,y+16,color);}}
}'''
sources['net/minecraft/client/gui/screens/Screen.java']=r'''package net.minecraft.client.gui.screens;
import net.minecraft.client.*;import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.components.events.*;import net.minecraft.client.input.*;import net.minecraft.network.chat.Component;import java.util.*;
public class Screen{protected final Minecraft minecraft=Minecraft.getInstance();protected final Font font=Minecraft.getInstance().font;protected final Component title;public int width=960,height=500;public final List<AbstractWidget> widgets=new ArrayList<>();private GuiEventListener focus;
 public Screen(Component c){title=c;}public int blurCalls;public void extractBlurredBackground(GuiGraphicsExtractor g){blurCalls++;}public void extractBackground(GuiGraphicsExtractor g,int x,int y,float d){}protected void init(){}public void initialize(){init();}public void rebuildWidgets(){widgets.clear();focus=null;init();}protected <T extends AbstractWidget>T addRenderableWidget(T b){widgets.add(b);return b;}public GuiEventListener getFocused(){return focus;}public void setFocused(GuiEventListener b){focus=b;for(var w:widgets)w.setFocused(w==b);}protected void setInitialFocus(GuiEventListener b){setFocused(b);}
 public void extractRenderState(GuiGraphicsExtractor g,int x,int y,float d){for(var b:widgets)b.render(g,x,y,d);}public void tick(){}public boolean charTyped(CharacterEvent e){if(focus instanceof EditBox b){b.insertText(e.text());return true;}return false;}public boolean keyPressed(KeyEvent e){if(e.key()==259&&focus instanceof EditBox b){int at=b.getCursorPosition();if(at>0){String v=b.getValue();b.setValue(v.substring(0,at-1)+v.substring(at));b.setCursorPosition(at-1);}return true;}return false;}public boolean mouseClicked(MouseButtonEvent e,boolean twice){for(var b:widgets)if(b.active&&b.isMouseOver(e.x(),e.y())){setFocused(b);if(b.press!=null)b.press.run();return true;}return false;}public boolean mouseScrolled(double x,double y,double h,double v){return false;}public boolean mouseDragged(MouseButtonEvent e,double x,double y){return false;}public boolean mouseReleased(MouseButtonEvent e){return false;}public void onClose(){}public void removed(){}public boolean isPauseScreen(){return true;}
}'''
