sources['net/minecraft/network/chat/Component.java']=r'''package net.minecraft.network.chat;import net.minecraft.util.FormattedCharSequence;public record Component(String text){public static Component literal(String t){return new Component(t);}public static Component translatable(String t){return literal(switch(t){case "block.minecraft.oak_log"->"Дубовое бревно";case "block.minecraft.stone"->"Камень";default->t;});}public static Component translatableWithFallback(String k,String f){return literal(f);}public String getString(){return text;}public FormattedCharSequence getVisualOrderText(){return new FormattedCharSequence(text);}}'''
