sources['cc/crafto/ui/client/CraftoUIClient.java']=r'''package cc.crafto.ui.client;
import cc.crafto.ui.*;import com.google.gson.*;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.screens.Screen;import java.util.*;
class CraftoUIClient{JsonObject lastTheme=new JsonObject(),city=new JsonObject();List<JsonObject> directory=List.of();List<String> summary=List.of();boolean townMember=true,personalAvailable=true,commandsAvailable=true,civicAvailable=true;CivicScreen civicReturn;ClientSettings settings=new ClientSettings();final PersonalPreferences preferences=new PersonalPreferences();final ContractHud contractHud=new ContractHud();final List<JsonObject> sent=new ArrayList<>();final List<String> launches=new ArrayList<>();
 PersonalPreferences preferences(){return preferences;}void send(Protocol.Kind k,JsonObject b){sent.add(b.deepCopy());}void commands(Screen s,String id){Minecraft.getInstance().gui.setScreen(new CommandScreen(this,s,id));}void civic(Screen s,String route){Minecraft.getInstance().gui.setScreen(new CivicScreen(this,s,route));}void personal(MenuScreen s,int tab){Minecraft.getInstance().gui.setScreen(new PersonalScreen(s,this,tab));}void launch(String id,PersonalScreen s){launches.add(id);}void request(String id){launches.add(id);}
}'''
sources['cc/crafto/ui/client/MenuScreen.java']=r'''package cc.crafto.ui.client;import com.google.gson.*;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;class MenuScreen extends Screen{boolean suspended,detached;int released;JsonObject theme=new JsonObject();MenuScreen(){super(Component.literal("Menu"));}void detach(){detached=true;}boolean isDetached(){return detached;}String menuId(){return "hub";}void releaseSession(){released++;}JsonObject resolvedTheme(){return theme;}void reloadTheme(){}}'''
